  'Não chegou em alguns minutos? Dê uma olhada no spam ou nas promoções. Se não estiver lá, mande de novo.': 'কয়েক মিনিটেও আসেনি? স্প্যাম বা প্রোমোশনে দেখো। সেখানেও না থাকলে আবার পাঠাও।',
