  'A sua Maravilha está pronta: defenda-a por 2 minutos!': 'তোমার বিস্ময় তৈরি: 2 মিনিট এটাকে রক্ষা করো!',
  'O computador terminou uma Maravilha: derrube-a em 2 minutos!': 'কম্পিউটার একটা বিস্ময় শেষ করেছে: 2 মিনিটের মধ্যে ভেঙে দাও!',
