  'Este jogo não se joga na sala.': 'এই খেলা রুমে খেলা হয় না।',
  'Ponha os seus navios no mar.': 'তোমার জাহাজগুলো সমুদ্রে রাখো।',
  'Esperando {nome} pôr os navios…': '{nome} জাহাজ রাখার অপেক্ষা…',
  'Os dois estão pondo os navios…': 'দুজনেই জাহাজ রাখছে…',
  'Navio de {n} casas': '{n} ঘরের জাহাজ',
  'Seus navios': 'তোমার জাহাজ',
  'Escolha um navio e toque no mar. Arraste para mudar de lugar.': 'একটা জাহাজ বেছে সমুদ্রে ছোঁও। জায়গা বদলাতে টানো।',
  'Sortear a frota': 'এলোমেলো নৌবহর',
