  'A troca está vazia.': 'বিনিময়টা খালি।',
  'Essa cidade não é de quem a troca diz.': 'বিনিময়ে যার বলা হয়েছে, এই শহর তার নয়।',
  'Venda os prédios do grupo antes de trocar.': 'বিনিময়ের আগে গ্রুপের দালানগুলো বিক্রি করো।',
  'Essa cidade não é sua.': 'এই শহর তোমার নয়।',
  'Só se constrói em cidade.': 'দালান শুধু শহরেই বানানো যায়।',
  'Para construir, é preciso ter todas as cidades do grupo.': 'বানাতে হলে গ্রুপের সব শহর তোমার থাকতে হবে।',
  'Resgate as cidades hipotecadas do grupo antes de construir.': 'বানানোর আগে গ্রুপের বন্ধক রাখা শহরগুলো ছাড়িয়ে নাও।',
  'Essa cidade já tem o máximo de prédios.': 'এই শহরে ইতিমধ্যে সর্বোচ্চ দালান আছে।',
