  "{nome} tem a palavra. Ouçam a defesa.": "কথা বলার পালা {nome}-এর। আত্মপক্ষ শোনো।",
  "{nome} terminou uma Maravilha: derrube-a em 2 minutos!": "{nome} একটা বিস্ময় শেষ করল: 2 মিনিটের মধ্যে ভেঙে দাও!",
  "{nome} tirou dados iguais e joga de novo.": "{nome} একই রকম পাশা পেল, আবার খেলবে।",
  "{nome} usou: {item}.": "{nome} ব্যবহার করল: {item}।",
  "{nome} vai escolher quem enfrentar.": "{nome} বাছবে কার সাথে লড়বে।",
  "{nome}: {tiros} tiros, {pct}% de acerto": "{nome}: {tiros}টা গুলি, {pct}% লক্ষ্যে",
  "1 contra 3": "1 বনাম 3",
  "2 contra 2": "2 বনাম 2",
  "A armadilha de {nome} disparou: quem sai junto?": "{nome}-এর ফাঁদ চলল: সাথে কে বেরোবে?",
  "A largada precisa de uma reta.": "শুরুর জন্য একটা সোজা অংশ লাগবে।",
  "A Maravilha de {nome} ficou de pé por 2 minutos.": "{nome}-এর বিস্ময় 2 মিনিট দাঁড়িয়ে রইল।",
  "A mesma posição pela terceira vez empata, e 20 lances só de dama sem comer também.": "একই অবস্থান তৃতীয়বার এলে ড্র, আর কিছু না খেয়ে শুধু রাজার 20 চালেও।",
  "À noite, veja quem os lobisomens atacaram. Uma poção salva essa pessoa e outra tira alguém do jogo; cada uma vale uma vez.": "রাতে দেখো নেকড়ে-মানবরা কাকে আক্রমণ করল। একটা ওষুধ তাকে বাঁচায় আর অন্যটা কাউকে খেলা থেকে বের করে দেয়; প্রতিটা একবারই।",
  "A partida se desencontrou entre os computadores e foi encerrada.": "কম্পিউটারগুলোর মধ্যে খেলার মিল ভেঙে গেল, তাই খেলা শেষ করা হল।",
  "A pedra que termina o lance na última fileira vira dama, que anda a diagonal inteira.": "যে ঘুঁটি শেষ সারিতে চাল শেষ করে সে রাজা হয়, যে পুরো কোনাকুনি চলে।",
  "A pista ainda não fecha a volta.": "ট্র্যাক এখনও পুরো চক্কর বানায়নি।",
  "A pista está curta demais.": "ট্র্যাক খুব ছোট।",
  "A pista passa por cima dela mesma.": "ট্র্যাক নিজের ওপর দিয়ে চলে গেছে।",
  "A pista precisa de mais peças.": "ট্র্যাকে আরও টুকরো লাগবে।",
  "A turma age antes nas duas rodadas seguintes.": "পরের দুই রাউন্ডে দল আগে চাল দেয়।",
  "A turma está decidindo.": "দল সিদ্ধান্ত নিচ্ছে।",
  "A turma inteira leva bem menos dano nesta rodada.": "এই রাউন্ডে পুরো দল অনেক কম ক্ষতি পায়।",
  "A turma recupera vida no fim de três rodadas.": "তিন রাউন্ড শেষে দল প্রাণ ফিরে পায়।",
