  "Um golpe forte de magia num inimigo só.": "একটা শত্রুর ওপর জাদুর জোরালো আঘাত।",
  "Um tiro que deixa o inimigo tonto: ele perde a vez.": "এমন গুলি যা শত্রুকে হতভম্ব করে: তার পালা চলে যায়।",
  "Um treino: a turma ficou mais forte.": "একটা অনুশীলন: দল আরও শক্তিশালী হল।",
  "Uma fonte: a turma recupera a vida e a energia.": "একটা ঝরনা: দল প্রাণ আর শক্তি ফিরে পায়।",
