  // Os mini-games e as insígnias (19/11/2026)
  "{nome} terminou uma Maravilha: defenda-a por 2 minutos!": "{nome} একটা বিস্ময় শেষ করল: 2 মিনিট সেটা রক্ষা করো!",
  "{nome} terminou uma Maravilha.": "{nome} একটা বিস্ময় শেষ করল।",
  "A Maravilha da outra equipe ficou de pé por 2 minutos.": "অন্য দলের বিস্ময় 2 মিনিট দাঁড়িয়ে ছিল।",
  "A Maravilha da sua equipe ficou de pé por 2 minutos.": "তোমার দলের বিস্ময় 2 মিনিট দাঁড়িয়ে ছিল।",
  "A outra equipe derrubou os dois centros da vila de vocês.": "অন্য দল তোমাদের দুটো গ্রাম-কেন্দ্রই ভেঙে দিল।",
  "A outra equipe desistiu.": "অন্য দল হাল ছেড়ে দিল।",
