  "A sua equipe desistiu.": "তোমার দল হাল ছেড়ে দিল।",
  "A sua equipe ficou fora da sala por muito tempo.": "তোমার দল অনেকক্ষণ রুমের বাইরে ছিল।",
  "Duas equipes de dois. Os robôs completam os lugares que faltam.": "দুজন করে দুটো দল। বাকি জায়গাগুলো রোবটরা পূরণ করে।",
  "Gênero": "লিঙ্গ",
  "Levadiça": "উত্তোলন সেতু",
  'Nenhuma conversa ainda. Toque em alguém na lista de pessoas da comunidade e escolha "Enviar mensagem".': "এখনও কোনো কথোপকথন নেই। কমিউনিটির লোকজনের তালিকায় কাউকে ট্যাপ করে \"বার্তা পাঠাও\" বেছে নাও।",
  "Varia": "ভিন্ন ভিন্ন",
  "Vitória de {nomes}": "{nomes}-এর জয়",
  "Vocês derrubaram os dois centros da vila da outra equipe.": "তোমরা অন্য দলের দুটো গ্রাম-কেন্দ্রই ভেঙে দিলে।",
  // Os mini-games e as insígnias (19/11/2026)
  "A cidade que ninguém compra vai a leilão. Hipotecar uma cidade dá dinheiro, mas ela não cobra aluguel.": "যে শহর কেউ কেনে না, সেটা নিলামে যায়। শহর বন্ধক রাখলে টাকা পাওয়া যায়, কিন্তু সেটা আর ভাড়া তোলে না।",
  "A dica acende a peça que move. O problema com dica não pontua; na corrida, ela tira 10 segundos.": "সংকেত সেই ঘুঁটিটা জ্বালায় যেটা নড়বে। সংকেত নেওয়া ধাঁধায় পয়েন্ট নেই; দৌড়ে, এতে ১০ সেকেন্ড কাটে।",
  "A manilha é o valor seguinte ao da vira e ganha de todas. Entre elas: ouros, espadas, copas e paus, o zap.": "মানিলা হলো ভিরার পরের মান, আর সবাইকে হারায়। নিজেদের মধ্যে: রুইতন, ইস্কাপন, হরতন আর চিড়িতন, মানে জ্যাপ।",
  "A última nave de cada volta sai.": "প্রতি ল্যাপের শেষ যানটা বাদ পড়ে।",
  "Abaixar": "নিচু হও",
  "Acertos em sequência: {n}": "টানা সঠিক: {n}",
  "Ande pelo dado e compre a capital onde parar. Quem para na cidade de outro paga aluguel.": "ছক্কা চেলে এগোও আর যে রাজধানীতে থামো সেটা কেনো। অন্যের শহরে যে থামে, সে ভাড়া দেয়।",
  "Cada linha, coluna e bloco de 3 × 3 tem os números de 1 a 9, sem repetir.": "প্রতিটি সারি, কলাম আর ৩ × ৩ ব্লকে ১ থেকে ৯ পর্যন্ত সংখ্যা থাকে, পুনরাবৃত্তি ছাড়া।",
  "Cada um recebe 3 cartas. Leva a mão quem ganhar 2 das 3 rodadas.": "প্রত্যেকে ৩টা তাস পায়। ৩ রাউন্ডের ২টা যে জেতে, হাত তার।",
  "Campeonato": "চ্যাম্পিয়নশিপ",
  "Com 11 pontos, a dupla vê as cartas e decide se joga a mão de onze. Vence quem chegar a 12.": "১১ পয়েন্টে, জুটি তাস দেখে ঠিক করে এগারোর হাত খেলবে কি না। যে ১২-তে পৌঁছায়, সে জেতে।",
  "Com a região inteira, construa até 4 prédios: o aluguel sobe a cada um.": "পুরো অঞ্চল হাতে থাকলে ৪টা পর্যন্ত বাড়ি বানাও: প্রতিটায় ভাড়া বাড়ে।",
  "Com estrelas, o soco forte (★) gasta todas de uma vez e dói mais.": "তারা থাকলে, জোরালো ঘুষি (★) সবগুলো একবারে খরচ করে আর বেশি লাগে।",
  "Dica": "সংকেত",
  "Dica: este problema não pontua": "সংকেত: এই ধাঁধায় পয়েন্ট নেই",
  "Dica: tira 10 segundos": "সংকেত: ১০ সেকেন্ড কাটে",
  "Eliminação": "এলিমিনেশন",
  "Encoste uma pedra numa ponta da mesa com o mesmo número.": "টেবিলের কোনো প্রান্তে একই সংখ্যার ঘুঁটি লাগাও।",
  "Escolha a casa e depois o número. O lápis anota só para você.": "ঘর বেছে নাও, তারপর সংখ্যা। পেনসিলের লেখা শুধু তোমার জন্য।",
  "Esquive do golpe e soque logo depois: é o contra-ataque, e vale estrela.": "ঘুষি এড়িয়ে সঙ্গে সঙ্গে মারো: এটাই পাল্টা আক্রমণ, আর এতে তারা মেলে।",
  "Fora da corrida na volta {n}.": "ল্যাপ {n}-এ দৌড় থেকে বাদ।",
  "Força das cartas": "তাসের শক্তি",
  "Ganha o maior patrimônio no fim das rodadas, ou quem sobrar.": "রাউন্ড শেষে যার সম্পদ সবচেয়ে বেশি সে জেতে, নয়তো যে শেষ পর্যন্ত টিকে থাকে।",
  "Iniciante": "শিক্ষানবিশ",
  "Mestre": "ওস্তাদ",
  "Na sequência, cada acerto traz um problema mais difícil, e o primeiro erro acaba.": "টানা মোডে, প্রতিটি সঠিক উত্তর আরও কঠিন ধাঁধা আনে, আর প্রথম ভুলেই শেষ।",
  "O número pequeno no botão diz quantos ainda faltam.": "বোতামের ছোট সংখ্যাটা বলে আর কয়টা বাকি।",
  "Os cinco traçados seguidos contra o computador, com pontos.": "পাঁচটা ট্র্যাক পরপর, কম্পিউটারের বিরুদ্ধে, পয়েন্টসহ।",
  "Peça truco e a mão vale 3. Quem responde aceita, corre ou aumenta para 6, 9 ou 12.": "ট্রুকো ডাকো, হাতের দাম হয় ৩। যে জবাব দেয় সে রাজি হয়, পালায় বা ৬, ৯ বা ১২-তে বাড়ায়।",
  "Quem bate fica sem pedras e leva os pontos das mãos dos outros. Trancado, leva quem tem menos pontos na mão.": "যে ঘুঁটি শেষ করে, সে বাকিদের হাতের পয়েন্ট নিয়ে নেয়। খেলা আটকে গেলে, যার হাতে সবচেয়ে কম পয়েন্ট, সে নেয়।",
  "Sem pedra que sirva, compre. Sem nada para comprar, a vez passa.": "মেলে এমন ঘুঁটি না থাকলে তোলো। তোলার কিছু না থাকলে পালা চলে যায়।",
  "Sequência": "টানা",
  "Soque quando a luva brilhar: o golpe para e você ganha uma estrela.": "দস্তানা ঝলকালে মারো: ঘুষি থেমে যায় আর তুমি তারা পাও।",
  "Treino livre": "ফ্রি প্র্যাকটিস",
