  "{n} capitais": "{n}টি রাজধানী",
  "{nome} aprendeu {golpe}!": "{nome} {golpe} শিখে ফেলল!",
  "{nome} deu {bicho} para você cuidar.": "{nome} তোমাকে দেখাশোনার জন্য {bicho} দিল।",
  "{nome} esqueceu {antigo} e aprendeu {golpe}.": "{nome} {antigo} ভুলে গিয়ে {golpe} শিখল।",
  "{nome} parou com tudo valendo: +{n}": "{nome} STOP চেপেছে, আর সব উত্তরই গোনা হয়েছে: +{n}",
  "{nome} quer aprender {golpe}, mas já sabe 4 golpes.": "{nome} {golpe} শিখতে চায়, কিন্তু আগেই ৪টি আঘাত জানে।",
