  "{nome} vai voltar para o mato. Tem certeza?": "{nome} আবার ঘাসবনে ফিরে যাবে। নিশ্চিত?",
  "A geladeira pifou: pague {valor}.": "ফ্রিজ নষ্ট হয়ে গেছে: {valor} দাও।",
  "A pedra não come para trás": "ঘুঁটি পেছনে খায় না",
  "A restituição do imposto caiu na conta: receba {valor}.": "করের ফেরত টাকা অ্যাকাউন্টে এসেছে: {valor} নাও।",
  "A toca está vazia.": "গর্ত খালি।",
  "A turma fez uma vaquinha: cada um te dá {valor}.": "দলের সবাই চাঁদা তুলেছে: প্রত্যেকে তোমাকে {valor} দেয়।",
  "Aceitar que não vale": "মেনে নাও যে চলবে না",
  "Achou um atalho: avance 5 casas.": "শর্টকাট পেয়েছ: ৫ ঘর এগোও।",
  "Alta temporada em {lugares}: os aluguéis dobram por uma rodada.": "{lugares}-এ ভরা মৌসুম: এক রাউন্ডের জন্য ভাড়া দ্বিগুণ।",
  "As duas diagonais também têm os números de 1 a 9.": "দুটো কর্ণেও ১ থেকে ৯ পর্যন্ত সংখ্যা থাকে।",
  "As escuras não fazem dois três abertos de uma vez": "কালো ঘুঁটি একসঙ্গে দুটো খোলা তিন বানায় না",
  "As escuras não podem fazer dois três abertos de uma vez.": "কালো ঘুঁটি একসঙ্গে দুটো খোলা তিন বানাতে পারে না।",
  "Baixa temporada em {lugares}: os aluguéis caem pela metade por uma rodada.": "{lugares}-এ মন্দা মৌসুম: এক রাউন্ডের জন্য ভাড়া অর্ধেক।",
  "Batidas especiais: carroça e lá-e-ló valem o dobro": "বিশেষ জেতা: জোড়া আর দুই প্রান্তে মেলা ঘুঁটি দ্বিগুণ",
  "Brasil inteiro": "পুরো ব্রাজিল",
  "Captura: cercar duas pedras do outro tira as duas": "দখল: প্রতিপক্ষের দুটো ঘুঁটি ঘিরলে দুটোই উঠে যায়",
  "Carroça!": "জোড়া!",
  "Cenoura dourada": "সোনালি গাজর",
  "Chá forte": "কড়া চা",
  "Chegou o IPTU: pague {valor} por cidade sua.": "সম্পত্তি কর এসেছে: তোমার প্রতিটি শহরের জন্য {valor} দাও।",
  "Chuva de estrelas": "তারার বৃষ্টি",
  "Com a captura, cercar duas pedras do outro entre duas suas tira as duas; cinco capturas também vencem.": "দখলের নিয়মে, প্রতিপক্ষের দুটো ঘুঁটি নিজের দুটোর মাঝে ঘিরলে দুটোই উঠে যায়; পাঁচবার দখল করলেও জেতা যায়।",
  "Com a restrição 3-3, as escuras não podem fazer dois três abertos de uma vez.": "৩-৩ নিষেধে কালো ঘুঁটি একসঙ্গে দুটো খোলা তিন বানাতে পারে না।",
  "Com as batidas especiais, bater com carroça ou com a pedra que serve nas duas pontas vale o dobro; a carroça nas duas pontas, o quádruplo.": "বিশেষ জেতায়, জোড়া দিয়ে বা দুই প্রান্তেই মেলে এমন ঘুঁটি দিয়ে শেষ করলে দ্বিগুণ; দুই প্রান্তে মেলা জোড়া হলে চারগুণ।",
  "Consulta no dentista: pague {valor}.": "দাঁতের ডাক্তারের ফি: {valor} দাও।",
