  "Sai um animal secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a classe, a dieta, onde ele vive e o peso. Quem acertar com menos chutes ganha mais pontos.": "একটা গোপন প্রাণী বাছা হয়, আর সবাই অনুমান করে। প্রতিটি অনুমান দেখায় গোপনটার সঙ্গে কী মেলে: শ্রেণি, খাদ্য, কোথায় থাকে আর ওজন। যে কম অনুমানে মেলায়, সে বেশি পয়েন্ট পায়।",
  "Sai um dinossauro secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: o período, a dieta, o grupo, o comprimento e onde ele foi achado. Quem acertar com menos chutes ganha mais pontos.": "একটা গোপন ডাইনোসর বাছা হয়, আর সবাই অনুমান করে। প্রতিটি অনুমান দেখায় গোপনটার সঙ্গে কী মেলে: যুগ, খাদ্য, দল, দৈর্ঘ্য আর কোথায় পাওয়া গেছে। যে কম অনুমানে মেলায়, সে বেশি পয়েন্ট পায়।",
  "Sai um elemento químico secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a família, o estado físico, o período, o grupo e o número atômico. Quem acertar com menos chutes ganha mais pontos.": "একটা গোপন রাসায়নিক মৌল বাছা হয়, আর সবাই অনুমান করে। প্রতিটি অনুমান দেখায় গোপনটার সঙ্গে কী মেলে: পরিবার, ভৌত অবস্থা, পর্যায়, গ্রুপ আর পারমাণবিক সংখ্যা। যে কম অনুমানে মেলায়, সে বেশি পয়েন্ট পায়।",
  "Sai um estado secreto do Brasil, e cada um chuta outros. Cada chute mostra a distância e a direção até o secreto, a região, a população, a área, o litoral e a fronteira com outro país. Quem acertar com menos chutes ganha mais pontos.": "ব্রাজিলের একটা গোপন রাজ্য বাছা হয়, আর সবাই অনুমান করে। প্রতিটি অনুমান দেখায় গোপনটা পর্যন্ত দূরত্ব আর দিক, অঞ্চল, জনসংখ্যা, আয়তন, উপকূল আর অন্য দেশের সঙ্গে সীমান্ত। যে কম অনুমানে মেলায়, সে বেশি পয়েন্ট পায়।",
